__NUXT_JSONP__("/posts/back-to-ui-work-with-sketch-and-invision", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E,F,G,H,I,J,K){return {data:[{post:{slug:x,description:"Building a design system with Sketch and UI design workflow improvement in 2021",title:"Back to heavy UI work with Sketch",type:j,imgCover:x,tags:["sketch","UI","UX","invision","zeplin","miscs",j],createdAt:"2021-04-17T00:00:00.000Z",toc:[{id:y,depth:k,text:z},{id:A,depth:k,text:B},{id:C,depth:k,text:t},{id:D,depth:k,text:E},{id:r,depth:k,text:F}],body:{type:"root",children:[{type:b,tag:l,props:{id:y},children:[{type:b,tag:d,props:{href:"#context",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:z}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"These last weeks, I had to put aside a lot of my development work to focus on building a whole UI design for an upcoming "},{type:b,tag:d,props:{href:"https:\u002F\u002Fwww.natixis.com\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Natixis"}]},{type:a,value:" inner service (can't mention it at present time for privacy purpose)."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Regarding UI design, my tool of choice remains Sketch for the time being. I work with Sketch on a frequently basis to quickly design some of the landing pages I then have to build. I didn't improve my Sketch workflow a lot these last years considering a limited usage."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"But this time I had to roll up my sleeves as the job is about building a whole design system 💪"}]},{type:a,value:c},{type:b,tag:l,props:{id:A},children:[{type:b,tag:d,props:{href:"#sketch-improvements-with-new-plugins",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:B}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"First and foremost, I needed to seriously level-up my Sketch productivity, so I read a lot about the topic and got mostly 4 essential plugins in my toolbelt :"}]},{type:a,value:c},{type:b,tag:"ul",props:{},children:[{type:a,value:c},{type:b,tag:s,props:{},children:[{type:b,tag:d,props:{href:"https:\u002F\u002Fsketchrunner.com\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Sketch Runner"}]},{type:a,value:": this one acts like the famous "},{type:b,tag:d,props:{href:"https:\u002F\u002Fwww.alfredapp.com\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Alfred"}]},{type:a,value:" (mac OS) allowing us to quicky jump-to, insert, create, apply and install anything through a convenient search bar. A real game-changer to speed-up workflow using keyboard only!"}]},{type:a,value:c},{type:b,tag:s,props:{},children:[{type:b,tag:d,props:{href:"https:\u002F\u002Fgithub.com\u002Fsonburn\u002Fsymbol-organizer",rel:[f,g,h],target:i},children:[{type:a,value:"Symbol organiser"}]},{type:a,value:": instantly re-organize the usually messy symbols page in a single shortcut"}]},{type:a,value:c},{type:b,tag:s,props:{},children:[{type:b,tag:d,props:{href:"https:\u002F\u002Fgithub.com\u002Fbomberstudios\u002Fartboard-manager",rel:[f,g,h],target:i},children:[{type:a,value:"Artboard manager"}]},{type:a,value:": auto place and space artboards to always get a structured grid in our canvas"}]},{type:a,value:c},{type:b,tag:s,props:{},children:[{type:b,tag:d,props:{href:"https:\u002F\u002Fgithub.com\u002Foodesign\u002Fduplicate-under",rel:[f,g,h],target:i},children:[{type:a,value:"Duplicate under"}]},{type:a,value:": A small extension allowing us to placing copies under the original in the layer list"}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Additionally, I set up a few shortcuts that didn't exist natively (insert images, merge all windows, collapse all groups...). I would say I now go twice as fast using these tools, so it's really worth the investment 👍"}]},{type:a,value:c},{type:b,tag:l,props:{id:C},children:[{type:b,tag:d,props:{href:"#sketch-cloud",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:t}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"As a front-end developer, Git is an essential part of my workflow to version all my work. But I stayed stuck in the past regarding UI work, as I'm still manually versioning every file iteration."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"I heard from tools such as "},{type:b,tag:d,props:{href:"https:\u002F\u002Fwww.abstract.com\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Abstract"}]},{type:a,value:" but didn't take time to look at it so far. But I also heard about "},{type:b,tag:d,props:{href:"https:\u002F\u002Fwww.sketch.com\u002Fdocs\u002Fsketch-cloud\u002F",rel:[f,g,h],target:i},children:[{type:a,value:t}]},{type:a,value:" that recently opened up."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"As a licensed user, I decided to give a try and switch for a team licence to be able to use it. Sketch cloud solves the versioning problem as every \"save\" action acts like a "},{type:b,tag:G,props:{},children:[{type:a,value:"git commit"}]},{type:a,value:" and we can then roll back to a previous version if needed. But one of the main feature is to collaborate with other team members of the declared Sketch team within a space."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Every team member can refer to a single cloud hosted file. We can also embed fonts within each file so that missing fonts across users is not a problem anymore 🦚"}]},{type:a,value:c},{type:b,tag:l,props:{id:D},children:[{type:b,tag:d,props:{href:"#invision--invision-dsm",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:E}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Regarding showcasing artboards, I have been using "},{type:b,tag:d,props:{href:"https:\u002F\u002Fwww.invisionapp.com\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Invision"}]},{type:a,value:" from a while now through the "},{type:b,tag:d,props:{href:"https:\u002F\u002Fwww.invisionapp.com\u002Fcraft",rel:[f,g,h],target:i},children:[{type:a,value:"Craft"}]},{type:a,value:" plugin, and am still using it. But this time, I have been asked to develop a design system from the created UI."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"I benchmarked some tools and finally found that "},{type:b,tag:d,props:{href:"https:\u002F\u002Fwww.invisionapp.com\u002Fdesign-system-manager",rel:[f,g,h],target:i},children:[{type:a,value:"Invision Design System Manager"}]},{type:a,value:", aka "},{type:b,tag:G,props:{},children:[{type:a,value:"DSM"}]},{type:a,value:", was already part of the Invision plan I'm using to build this kind of stuff."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Invision DSM provides a cloud hosted space to expose a complete design system that we can build from any Sketch file. We can quickly extract any symbol, color, or style in an organised way, and complete it with a custom text description. It's also very easy to maintain it with a single push from our most recent version of our Sketch file reference."}]},{type:a,value:c},{type:b,tag:l,props:{id:r},children:[{type:b,tag:d,props:{href:"#next",ariaHidden:m,tabIndex:n},children:[{type:b,tag:o,props:{className:[p,q]},children:[]}]},{type:a,value:F}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"I also wanted to talk about the "},{type:b,tag:d,props:{href:"https:\u002F\u002Fzeplin.io\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Zeplin"}]},{type:a,value:" service that I will probably deploy to easily hand-off artboards to developers. Kind of a more elaborated version of Invision Inspect, but I still have to work with it before being able to evaluate this tool."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Another thing I didn't talk about is that I took advantage of using a design system ui kit called "},{type:b,tag:d,props:{href:"https:\u002F\u002Fcabanadesignsystem.com\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Cabana"}]},{type:a,value:" to help me organize my design system following Sketch best practices."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"So much things learned!"}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"It's sometimes good to be back on another part of the web domain, as it will surely help me be more efficient producing UIs."}]}]},dir:"\u002Fposts",path:"\u002Fposts\u002Fback-to-ui-work-with-sketch-and-invision",extension:".md",updatedAt:"2025-10-10T15:29:17.519Z"},relatedPosts:[{title:"Nuxt.js puzzle game development - WIP#4",type:j,imgCover:"nuxt-js-puzzle-game-development-wip4",tags:["nuxt","cordova",u,j],createdAt:"2019-12-27T00:00:00.000Z",path:"\u002Fposts\u002Fnuxt-js-puzzle-game-development-wip4"},{title:"Building a 2D runner game with Next.js",type:j,imgCover:"building-a-2d-runner-game-with-nextjs",tags:[u,r,H,I,J,K,v,j],createdAt:"2024-08-17T00:00:00.000Z",path:"\u002Fposts\u002Fbuilding-a-2D-runner-game-with-nextjs"},{title:"Animated movie WIP#0",type:j,imgCover:"animated-movie-wip0",tags:[v,j],createdAt:"2018-01-01T00:00:00.000Z",path:"\u002Fposts\u002Fanimated-movie-wip0"},{title:"Building a Where's Waldo game with Next.js",type:j,imgCover:"building-a-where-s-waldo-game-with-nextjs",tags:[u,r,H,I,J,K,v,j],createdAt:"2024-04-01T00:00:00.000Z",path:"\u002Fposts\u002Fbuilding-a-where-s-waldo-game-with-nextjs"}]}],fetch:[{counter:7},{counter:w},{counter:3},{counter:w},{counter:w},{counter:24},{counter:71}],mutations:[]}}("text","element","\n","a","p","nofollow","noopener","noreferrer","_blank","article",2,"h2","true",-1,"span","icon","icon-link","next","li","Sketch Cloud","games","cinema 4D",1,"back-to-ui-work-with-sketch-and-invision","context","Context","sketch-improvements-with-new-plugins","Sketch improvements with new plugins","sketch-cloud","invision--invision-dsm","Invision & Invision DSM","Next","em","framer-motion","Tailwind","Figma","devs")));